{% assign wanted = include.tags | split: "," %}
{% assign shown = 0 %}
{% for post in site.posts %}
  {% if shown >= 10 %}{% break %}{% endif %}
  {% assign match = false %}
  {% for w in wanted %}{% if post.tags contains w %}{% assign match = true %}{% endif %}{% endfor %}
  {% if match %}
  {% assign shown = shown | plus: 1 %}


    {{ post.title | xml_escape }}
    {{ post.excerpt | xml_escape }}
    {{ post.date | date_to_rfc822 }}
    {{ post.url | prepend: site.baseurl | prepend: site.url }}
    {{ post.url | prepend: site.baseurl | prepend: site.url }}
    {% include rss-image-enclosure.html post=post %}
    {% for tag in post.tags %}
    {{ tag | xml_escape }}
    {% endfor %}

  {% endif %}
{% endfor %}
